// + - * / on non-negative integers, no parentheses; '/' truncates toward zero.
// O(n) time, O(1) memory: instead of a stack keep the finished sum plus the last term.
int calculate(const std::string& s) {
  long long total = 0, last = 0, num = 0;
  char op = '+';                                   // operator that precedes `num`
  for (size_t i = 0; i <= s.size(); ++i) {
    char c = i < s.size() ? s[i] : '\0';
    if (std::isdigit(static_cast<unsigned char>(c))) { num = num * 10 + (c - '0'); continue; }
    if (c == ' ') continue;
    // c is an operator or the end of input: apply the pending operator to num
    switch (op) {
      case '+': total += last; last = num; break;
      case '-': total += last; last = -num; break;
      case '*': last *= num; break;                // binds to the previous term only
      case '/': last /= num; break;                // C++ '/' truncates toward zero
    }
    op = c;
    num = 0;
  }
  return static_cast<int>(total + last);
}

