// + - * / and parentheses, non-negative integer literals, '/' truncates toward zero.
// Recursive descent:  expr := term (('+'|'-') term)*
//                     term := factor (('*'|'/') factor)*
//                     factor := number | '(' expr ')'
class Calculator {
  const std::string& s_;
  size_t i_ = 0;
  void skip() { while (i_ < s_.size() && s_[i_] == ' ') ++i_; }
  char peek() { skip(); return i_ < s_.size() ? s_[i_] : '\0'; }

  long long factor() {
    if (peek() == '(') {
      ++i_;                                   // '('
      long long v = expr();
      peek(); ++i_;                           // ')'
      return v;
    }
    long long v = 0;
    while (i_ < s_.size() && std::isdigit(static_cast<unsigned char>(s_[i_])))
      v = v * 10 + (s_[i_++] - '0');
    return v;
  }
  long long term() {
    long long v = factor();
    for (char c = peek(); c == '*' || c == '/'; c = peek()) {
      ++i_;
      long long r = factor();
      v = (c == '*') ? v * r : v / r;
    }
    return v;
  }
  long long expr() {
    long long v = term();
    for (char c = peek(); c == '+' || c == '-'; c = peek()) {
      ++i_;
      long long r = term();
      v = (c == '+') ? v + r : v - r;
    }
    return v;
  }
public:
  explicit Calculator(const std::string& s) : s_(s) {}
  int eval() { return static_cast<int>(expr()); }
};

int calculate(const std::string& s) { return Calculator(s).eval(); }

