std::string decodeString(const std::string& s) {
  std::stack<std::pair<std::string, int>> st;   // (text before '[', repeat count)
  std::string cur;
  int k = 0;
  for (char c : s) {
    if (std::isdigit(static_cast<unsigned char>(c))) {
      k = k * 10 + (c - '0');                   // counts can have several digits: "12[a]"
    } else if (c == '[') {
      st.push({std::move(cur), k});             // save the outer context
      cur.clear();
      k = 0;
    } else if (c == ']') {
      auto [prev, times] = std::move(st.top());
      st.pop();
      prev.reserve(prev.size() + cur.size() * times);
      for (int i = 0; i < times; ++i) prev += cur;
      cur = std::move(prev);                    // back to the outer level
    } else {
      cur += c;
    }
  }
  return cur;
}

bool isValid(const string& s) {
    vector<char> st;                         // open brackets not yet closed
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push_back(c);
            continue;
        }
        char want = (c == ')') ? '(' : (c == ']') ? '[' : '{';
        if (st.empty() || st.back() != want) return false;
        st.pop_back();
    }
    return st.empty();                       // leftovers = unclosed openers
}

