int sumSubarrayMins(const vector<int>& a) {
    const long long MOD = 1'000'000'007;
    int n = a.size();
    vector<int> left(n), right(n), st;
    // left[i]: distance to previous STRICTLY smaller element
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && a[st.back()] >= a[i]) st.pop_back();
        left[i] = st.empty() ? i + 1 : i - st.back();
        st.push_back(i);
    }
    st.clear();
    // right[i]: distance to next smaller-OR-EQUAL element
    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && a[st.back()] > a[i]) st.pop_back();
        right[i] = st.empty() ? n - i : st.back() - i;
        st.push_back(i);
    }
    long long sum = 0;
    for (int i = 0; i < n; ++i)
        sum = (sum + (long long)a[i] * left[i] % MOD * right[i]) % MOD;
    return (int)sum;
}

