int maximalRectangle(const vector<vector<char>>& m) {
    if (m.empty() || m[0].empty()) return 0;
    int C = m[0].size(), best = 0;
    vector<int> h(C + 1, 0);           // h[C] stays 0: sentinel
    vector<int> st;
    for (const auto& row : m) {
        // histogram of consecutive '1's ending at this row
        for (int j = 0; j < C; ++j) h[j] = row[j] == '1' ? h[j] + 1 : 0;
        st.clear();
        for (int j = 0; j <= C; ++j) {
            while (!st.empty() && h[st.back()] >= h[j]) {
                int height = h[st.back()];
                st.pop_back();
                int left = st.empty() ? -1 : st.back();
                best = max(best, height * (j - left - 1));
            }
            st.push_back(j);
        }
    }
    return best;
}

