vector<int> exclusiveTime(int n, const vector<string>& logs) {
    vector<int> res(n, 0), st;        // st: call stack of function ids
    int prev = 0;                     // first time unit not yet attributed
    for (const string& log : logs) {
        size_t a = log.find(':'), b = log.rfind(':');
        int id = stoi(log.substr(0, a));
        int t = stoi(log.substr(b + 1));
        if (log[a + 1] == 's') {
            if (!st.empty()) res[st.back()] += t - prev;   // caller ran until t-1
