class DoubleEndedStack:
    def __init__(self, cap: int):
        self.buf = [None] * cap
        self.cap = cap
        self.head = 0          # index of the front element
        self.size = 0

    def push_front(self, x):
        if self.size == self.cap:
            raise IndexError("full")
        self.head = (self.head - 1) % self.cap
        self.buf[self.head] = x
        self.size += 1

    def push_back(self, x):
        if self.size == self.cap:
            raise IndexError("full")
        self.buf[(self.head + self.size) % self.cap] = x
        self.size += 1

    def pop_front(self):
        if self.size == 0:
            raise IndexError("empty")
        x = self.buf[self.head]
        self.buf[self.head] = None     # drop the reference
        self.head = (self.head + 1) % self.cap
        self.size -= 1
        return x

    def pop_back(self):
        if self.size == 0:
            raise IndexError("empty")
        i = (self.head + self.size - 1) % self.cap
        x, self.buf[i] = self.buf[i], None
        self.size -= 1
        return x

#include <mutex>
#include <condition_variable>

class ConcurrentQueue {
    struct Node { int val; Node* next; };
    Node* head_ = nullptr;
    Node* tail_ = nullptr;
    std::mutex m_;
    std::condition_variable cv_;

    int popLocked() {                       // caller holds m_, queue non-empty
        Node* n = head_;
        head_ = n->next;
        if (!head_) tail_ = nullptr;        // queue became empty
        int v = n->val;
        delete n;
        return v;
    }
public:
    ConcurrentQueue() = default;
    ConcurrentQueue(const ConcurrentQueue&) = delete;
    ConcurrentQueue& operator=(const ConcurrentQueue&) = delete;
    ~ConcurrentQueue() { while (head_) { Node* n = head_->next; delete head_; head_ = n; } }

    void push(int v) {
        Node* n = new Node{v, nullptr};     // allocate outside the lock
        {
            std::lock_guard<std::mutex> lk(m_);
            if (tail_) tail_->next = n; else head_ = n;
            tail_ = n;
        }
        cv_.notify_one();
    }
    int pop() {
        std::unique_lock<std::mutex> lk(m_);
        cv_.wait(lk, [&] { return head_ != nullptr; });   // loops on spurious wakeups
        return popLocked();
    }
    bool tryPop(int& out) {
        std::lock_guard<std::mutex> lk(m_);
        if (!head_) return false;
        out = popLocked();
        return true;
    }
};

