class HitCounter:
    W = 300

    def __init__(self):
        self.times = [0] * self.W     # which second each bucket holds
        self.counts = [0] * self.W

    def hit(self, timestamp: int) -> None:
        i = timestamp % self.W
        if self.times[i] != timestamp:    # stale bucket from an older lap
            self.times[i] = timestamp
            self.counts[i] = 0
        self.counts[i] += 1

    def get_hits(self, timestamp: int) -> int:
        return sum(c for t, c in zip(self.times, self.counts)
                   if timestamp - t < self.W)

