#include <vector>
#include <algorithm>
#include <numeric>

int countDrops(long long L, const std::vector<long long>& pos, const std::vector<long long>& speed) {
    int n = pos.size();
    std::vector<int> idx(n);
    std::iota(idx.begin(), idx.end(), 0);
    std::sort(idx.begin(), idx.end(), [&](int a, int b) { return pos[a] > pos[b]; });
    int groups = 0;
    long long bd = 0, bv = 1;               // slowest arrival so far = bd / bv
    for (int i : idx) {
        long long d = L - pos[i], v = speed[i];
        // new group iff d / v > bd / bv  <=>  d * bv > bd * v  (no floats)
        if (groups == 0 || d * bv > bd * v) {
            ++groups;
            bd = d; bv = v;
        }
    }
    return groups;
}
